for scene in SCENES:subprocess.run(['node','tests/gpu-fixture.mjs',scene],cwd=ROOT,check=True,stdout=subprocess.DEVNULL)
out={'sourceSha256':hashlib.sha256((ROOT/'src/gpu/sparse-flip.js').read_bytes()).hexdigest(),'build':'CYBR FLIP III','backend':'SparseGPUFLIP','tests':[],'javascriptErrors':[]}
with sync_playwright() as p:
 b=launch(p,2);page=b.new_page(viewport={'width':320,'height':240});page.set_default_timeout(120000)
 page.on('pageerror',lambda e:out['javascriptErrors'].append(str(e)))
 html='<canvas id="c" width="320" height="240"></canvas>'+'<script>'+(ROOT/'vendor/three.global.js').read_text()+'</script>'+'<script>'+(ROOT/'src/gpu/sparse-flip.js').read_text()+'</script>'
 page.set_content(html);page.evaluate("window.R=new THREE.WebGLRenderer({canvas:document.querySelector('canvas')});window.fixture=null")
 def test(name,fn):
  start=time.time()
  try:
   evidence=fn();out['tests'].append({'name':name,'passed':True,'seconds':time.time()-start,'evidence':evidence});print('GPU PASS',name,json.dumps(evidence),flush=True)
  except Exception as e:
   out['tests'].append({'name':name,'passed':False,'seconds':time.time()-start,'error':str(e)});print('GPU FAIL',name,str(e),flush=True)
  out['passed']=sum(t['passed'] for t in out['tests']);out['failed']=len(out['tests'])-out['passed'];(ROOT/'tests/gpu-solver-iii.json').write_text(json.dumps(out,indent=2))
 for scene in SCENES:
  seed=json.loads((ROOT/'tests'/f'gpu-{scene}-seed.json').read_text())
  def case(seed=seed):
   return page.evaluate('''s=>{window.G?.dispose();window.G=new SparseGPUFLIP(R,s.config,new Float32Array(s.positions),new Float32Array(s.velocities));let records=[];for(let i=0;i<6;i++){G.step(1/120);const state=G.readState();const m=state.metrics;if(!m.finite||m.solidViolations||!m.pressure.converged)throw Error(JSON.stringify(m));records.push({time:m.time,particles:m.particles,pressure:m.pressure.relativeResidual,solidViolations:m.solidViolations});}return {records,last:G.lastMetrics,capabilities:G.capabilities};}''',seed)
  test(scene+' / six actual sparse GPU timesteps',case)
 # Controlled affine field, no inherited preset seeding.
 seed={'config':{'h':.2,'nx':16,'ny':16,'nz':16,'extent':[3.2]*3,'flip':.93,'density':1000,'surfaceTension':0,'pressureTolerance':1e-4,'affine':True,'gravity':[0,0,0],'obstacles':[],'maxParticles':100000,'seed':93},'positions':[],'velocities':[]}
 for i in range(6,26):
  for j in range(6,21):
   for k in range(6,26):seed['positions'] += [i*.1+.01,j*.1+.013,k*.1+.017];seed['velocities'] += [0,0,0]
 page.evaluate('s=>{window.G?.dispose();window.fixture=s;window.G=new SparseGPUFLIP(R,s.config,new Float32Array(s.positions),new Float32Array(s.velocities));}',seed)
 test('GPU affine P2G linear-field reproduction',lambda:page.evaluate('''()=>{const A=[.35,.22,-.18,-.13,.19,.41,.06,-.28,.11],b=[1.2,-.7,.4],p=new Float32Array(fixture.positions),v=new Float32Array(p.length),a=new Float32Array(G.count*9);for(let n=0;n<G.count;n++){a.set(A,n*9);for(let c=0;c<3;c++)v[n*3+c]=b[c]+A[c*3]*p[n*3]+A[c*3+1]*p[n*3+1]+A[c*3+2]*p[n*3+2];}G.beginCompute();G.uploadParticles(p,v,a);G.activate();G.transfer();const g=G.read(G.old),map=G.mapArray,dim=G.blockDims,w=G.atlasSize[0];let err=0,checked=0;for(let i=5;i<11;i++)for(let j=5;j<9;j++)for(let k=5;k<11;k++)for(let c=0;c<3;c++){const bi=Math.floor(i/8)+dim[0]*(Math.floor(j/8)+dim[1]*Math.floor(k/8)),id=map[bi*4]-1,x=(id%G.atlasColumns)*64+(i%8)+8*(j%8),y=Math.floor(id/G.atlasColumns)*8+k%8;const p=[(i+(c===0?0:.5))*.2,(j+(c===1?0:.5))*.2,(k+(c===2?0:.5))*.2],expected=b[c]+A[c*3]*p[0]+A[c*3+1]*p[1]+A[c*3+2]*p[2];err=Math.max(err,Math.abs(g[(y*w+x)*4+c]-expected));checked++;}G.endCompute();if(err>3e-6)throw Error('Affine transfer error '+err);return {sampledFaces:checked,maximumAbsoluteVelocityError:err};}'''))
 test('GPU viscosity dissipates a nonuniform velocity field',lambda:page.evaluate('''()=>{G.dispose();const s=fixture,c={...s.config,kinematicViscosity:.08};G=new SparseGPUFLIP(R,c,new Float32Array(s.positions),new Float32Array(s.velocities));const p=new Float32Array(s.positions),v=new Float32Array(p.length);for(let q=0;q<v.length;q++)v[q]=Math.sin(q*.371)*1.5;G.beginCompute();G.uploadParticles(p,v);G.activate();G.transfer();G.levelSet();const before=G.read(G.old);G.dt=.04;G.externalForces();const after=G.read(G.current);const energy=a=>a.reduce((sum,x,i)=>sum+(i%4<3?x*x:0),0),a=energy(before),b=energy(after);G.endCompute();if(!(b<a))throw Error('Viscosity failed to dissipate energy.');return {before:a,after:b,ratio:b/a,iterations:G.viscosityIterations};}'''))
 test('GPU append/grow retains every prior primary bit',lambda:page.evaluate('''()=>{const old=G.readState(true);G.beginCompute();const n=G.particleCapacity-G.count+100,p=new Float32Array(n*3),v=new Float32Array(n*3);for(let i=0;i<n;i++)p.set([1.4,1.3,1.4],i*3);G.appendParticles(p,v);G.endCompute();const next=G.readState(true);let exact=true;for(let i=0;i<old.positions.length;i++)if(old.positions[i]!==next.positions[i]||old.velocities[i]!==next.velocities[i])exact=false;for(let i=0;i<old.affine.length;i++)if(old.affine[i]!==next.affine[i])exact=false;if(!exact)throw Error('GPU growth changed prior state.');return {retainedParticles:old.positions.length/3,appendedParticles:n,finalCount:G.count,exact};}'''))
 test('Sparse allocation follows liquid, not the full virtual domain',lambda:page.evaluate('''()=>{G.dispose();const c={...fixture.config,nx:120,ny:80,nz:80,h:.04,extent:[4.8,3.2,3.2]},p=[],v=[];for(let x=.8;x<1.12;x+=.02)for(let y=.8;y<1.12;y+=.02)for(let z=.8;z<1.12;z+=.02){p.push(x,y,z);v.push(0,0,0);}G=new SparseGPUFLIP(R,c,new Float32Array(p),new Float32Array(v));G.beginCompute();G.activate();const dense=121*81*81,allocated=G.atlasSize[0]*G.atlasSize[1];G.endCompute();if(allocated>=dense*.1)throw Error('Sparse allocation unexpectedly dense.');return {particles:G.count,virtualGrid:[120,80,80],denseTexels:dense,allocatedTexels:allocated,activeBricks:G.blockCount,gridStorageFraction:allocated/dense,coarseFlagReadbackBytes:G.coarsePixels.byteLength};}'''))
 # Regression: FP32 recursive residual once crossed the target before b-Ap did.
 live_seed=json.loads(subprocess.check_output(['node','--input-type=module','-e',"import{FlipSolver,makePreset}from './src/flip.js';const c=makePreset('breach','live'),s=new FlipSolver(c);console.log(JSON.stringify({config:c,positions:Array.from(s.p.slice(0,s.count*3)),velocities:Array.from(s.v.slice(0,s.count*3))}));"],cwd=ROOT))
 def residual_guard():
  return page.evaluate("""async s=>{G.dispose();G=new SparseGPUFLIP(R,s.config,new Float32Array(s.positions),new Float32Array(s.velocities));let records=[],replacements=0;for(let i=0;i<12;i++){await G.advance(1/48);let m=G.readState().metrics;if(!m.pressure.converged||m.pressure.relativeResidual>m.pressure.target||!m.finite||m.solidViolations)throw Error(JSON.stringify(m));replacements+=m.pressure.residualReplacements;records.push({time:m.time,residual:m.pressure.relativeResidual,recursive:m.pressure.recursiveRelativeResidual,replacements:m.pressure.residualReplacements});}return {records,explicitResidualChecks:records.length,observedResidualReplacements:replacements};}""",live_seed)
 test('Explicit pressure residual is enforced after FP32 recursive convergence',residual_guard)
 capillary_seed=json.loads((ROOT/'tests/gpu-capillary-seed.json').read_text())
 test('GPU capillary boundary balances a prescribed constant curvature',lambda:page.evaluate("""s=>{G.dispose();G=new SparseGPUFLIP(R,s.config,new Float32Array(s.positions),new Float32Array(s.velocities));G.beginCompute();G.dt=1/120;G.activate();G.transfer();G.levelSet();const field=G.read(G.field);for(let i=0;i<field.length;i+=4)field[i+2]=50.;G.upload(G.field.textures[0],field);G.externalForces();G.pressure();const t=[...G.targets].find(t=>t.textures.includes(G.pressureState)),pressure=G.read(t,t.textures.indexOf(G.pressureState)),mask=G.read(G.mask),expected=s.config.surfaceTension*50;let err=0,count=0;for(let i=0;i<mask.length;i+=4)if(mask[i]>.5){err=Math.max(err,Math.abs(pressure[i]-expected));count++;}const divergence=G.divergenceStats();G.endCompute();if(!(count>0&&err<.001&&divergence.rms<.001))throw Error(JSON.stringify({count,err,divergence,expected}));return {fluidCells:count,expectedPressure:expected,maximumPressureError:err,divergenceAfter:divergence.rms};}""",capillary_seed))
 test('GPU zero-gravity surface-tension toggle changes actual primary velocity',lambda:page.evaluate("""s=>{G.dispose();const states=[];for(const sigma of [0,s.config.surfaceTension]){G=new SparseGPUFLIP(R,{...s.config,surfaceTension:sigma},new Float32Array(s.positions),new Float32Array(s.velocities));G.step(1/120);states.push(G.readState());G.dispose();}let difference=0,disabled=0;for(let i=0;i<states[0].velocities.length;i++){disabled=Math.max(disabled,Math.abs(states[0].velocities[i]));difference=Math.max(difference,Math.abs(states[0].velocities[i]-states[1].velocities[i]));}if(!(difference>1e-5&&disabled<1e-8))throw Error(JSON.stringify({difference,disabled}));G=new SparseGPUFLIP(R,s.config,new Float32Array(s.positions),new Float32Array(s.velocities));return {particles:G.count,maximumVelocityDifference:difference,maximumVelocityWithoutSurfaceTension:disabled};}""",capillary_seed))
